export const assets = {"README.md":"# Evaluation setup\n\nThis export is an undeployed Agent construct. Business evaluation has NOT RUN.\nFoundation controls and their CI checks remain mandatory and separate.\n\n1. Implement the Domain Harness using AGENTS.md/CLAUDE.md. Connect\n   `evaluation/agent_adapter.py` to the real local Agent, preserving tool evidence.\n2. Edit `evaluation/config.json` and dataset/evaluator files. You may defer both\n   when exporting. Blueprint cases are illustrative starters, not business acceptance.\n3. Dataset JSONL schema: `{\"id\":\"case-1\",\"input\":\"request\",\"expected\":\"optional expected text\"}`.\n   Map existing dataset columns to these keys. For a referenced S3 dataset, fetch it\n   with your own scoped credentials and set EVAL_DATASET_PATH; contents are not exported.\n4. Custom Python evaluator interface: `evaluate(case, result) -> {\"score\": 0.0..1.0,\n   \"reason\": \"evidence\"}`. result includes output and may include tool/trace data.\n   The platform packages uploaded source; it does not execute it. Review it before\n   running in a dedicated CI runner. Do not provide unneeded credentials or use\n   production credentials. Do not run untrusted code on a shared persistent runner.\n5. `pip install -r evaluation/requirements.txt`\n   then `python -m pytest evaluation/test_evaluation.py -q`.\n   Reports: evaluation/report.json. Missing configuration, an unimplemented adapter,\n   empty cases, invalid scores, runtime errors or scores below the inherited floor\n   fail the business check. They never count as a pass. Export itself is allowed.\n\n## AgentCore Evaluations\n\nChoose an existing built-in or custom evaluator ID. The shipped boto3 adapter\ncalls the on-demand Evaluate API with actual OpenTelemetry sessionSpans from the\nAgent adapter. Set AWS_REGION/AWS_DEFAULT_REGION and scoped AWS credentials in\nthat execution environment. An endpoint or a plain answer alone is insufficient.\nCustom evaluator provisioning (LLM judge or Lambda), online evaluation sampling,\nIAM and telemetry setup are separate deployment work; this export does not claim\nthose resources exist. Local Python is not automatically uploaded as an AgentCore\ncustom evaluator. Numeric [0,1] results are supported; other scales require an\nexplicit custom mapping. Dataset expected values are not automatically translated\ninto AgentCore reference inputs; add a domain-specific adapter when required.\n\nCI runs this package alongside existing Foundation controls, with a job timeout.\nIt uploads the report even on failure. Configure required checks for promotion;\nproduction also requires the separate release-bound human decision. Do not relax\nFoundation checks or mark an unconfigured business evaluation as approved.\n","test_evaluation.py":"\"\"\"Run with python -m pytest evaluation/test_evaluation.py -q. No deployed agent assumed.\"\"\"\nimport importlib.util\nimport json\nimport math\nimport os\nfrom pathlib import Path\nimport pytest\n\nROOT = Path(__file__).resolve().parent.parent\n\ndef module(path):\n    spec = importlib.util.spec_from_file_location(path.stem, path)\n    obj = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(obj)\n    return obj\n\ndef test_business_evaluation():\n    config = json.loads((ROOT / 'evaluation/config.json').read_text())\n    report = {'status': 'NOT_CONFIGURED', 'results': []}\n    target = ROOT / 'evaluation/report.json'\n    try:\n        if config['dataset']['source'] == 'later' or config['evaluator']['type'] == 'later':\n            pytest.fail('Business evaluation is NOT_CONFIGURED. Configure dataset/evaluator after export; no evaluation has passed.')\n        dataset = ROOT / 'evaluation/dataset.jsonl'\n        if config['dataset']['source'] == 'reference':\n            dataset = Path(os.environ.get('EVAL_DATASET_PATH', '/dataset-not-configured'))\n        cases = [json.loads(line) for line in dataset.read_text().splitlines() if line.strip()]\n        assert cases, 'Empty datasets never pass'\n        adapter = module(ROOT / 'evaluation/agent_adapter.py')\n        evaluator = module(ROOT / 'evaluation/evaluator.py')\n        report['status'] = 'FAILED'\n        for case in cases:\n            result = adapter.run(case)\n            assert isinstance(result, dict) and isinstance(result.get('output'), str), 'Agent adapter must return actual output'\n            verdict = evaluator.evaluate(case, result)\n            score = verdict.get('score')\n            assert isinstance(score, (int, float)) and not isinstance(score, bool) and math.isfinite(score) and 0 <= score <= 1, 'Evaluator must return a finite score in [0,1]'\n            assert isinstance(verdict.get('reason'), str) and verdict['reason'].strip(), 'Evaluator must explain the score'\n            report['results'].append({'id': case['id'], 'score': score, 'reason': verdict['reason']})\n        # The shared platform contract remains the floor; this file does not supply an override.\n        floor = json.loads((ROOT / 'gates/platform-gates.json').read_text())['threshold']\n        assert all(row['score'] >= floor for row in report['results']), 'Evaluation below the inherited threshold'\n        report['status'] = 'PASSED'\n    finally:\n        target.write_text(json.dumps(report, indent=2)+'\\n')\n","agent_adapter.py":"def run(case):\n    \"\"\"Call your implemented local agent. Return {'output': str, 'sessionSpans': [...] optional}.\n\n    Preserve actual tool/trace evidence. Do not replace this with expected text or\n    a direct model call that bypasses your Agent implementation.\n    \"\"\"\n    raise NotImplementedError('Connect this adapter to your local Agent before running business evaluation.')\n","evaluator.py":"def evaluate(case, result):\n    \"\"\"Starter deterministic expected-text check; replace with your business rubric.\"\"\"\n    expected = case.get('expected')\n    if not isinstance(expected, str) or not expected.strip():\n        raise ValueError('This evaluator requires expected text for every case.')\n    passed = expected.casefold() in result['output'].casefold()\n    return {'score': float(passed), 'reason': 'Expected text found' if passed else 'Expected text missing'}\n","agentcore_evaluator.py":"\"\"\"On-demand AgentCore Evaluations adapter. Requires boto3, AWS credentials and actual OTEL spans.\"\"\"\nimport json\nfrom pathlib import Path\n\ndef evaluate(case, result):\n    import boto3\n    config = json.loads((Path(__file__).parent / 'config.json').read_text())\n    spans = result.get('sessionSpans')\n    if not isinstance(spans, list) or not spans:\n        raise ValueError('AgentCore Evaluation requires real OpenTelemetry sessionSpans from your Agent.')\n    response = boto3.client('bedrock-agentcore').evaluate(\n        evaluatorId=config['evaluator']['id'], evaluationInput={'sessionSpans': spans})\n    rows = response.get('evaluationResults', [])\n    if not rows or any(row.get('errorCode') or row.get('errorMessage') for row in rows):\n        raise ValueError('AgentCore returned no successful evaluation results.')\n    values = [row.get('value') for row in rows]\n    if any(not isinstance(v, (int, float)) or not 0 <= v <= 1 for v in values):\n        raise ValueError('Configure a custom adapter for categorical or non-[0,1] rating scales; no implicit normalization.')\n    return {'score': min(values), 'reason': json.dumps(rows, default=str)}\n","evaluate.yml":"# platform-gate: v1 — configurable business evaluation, no fabricated passes\nname: eval-gate\non:\n  pull_request:\n  workflow_dispatch:\npermissions:\n  contents: read\njobs:\n  eval:\n    runs-on: ubuntu-latest\n    timeout-minutes: 10\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-python@v5\n        with:\n          python-version: '3.12'\n      - run: pip install -r evaluation/requirements.txt\n      - name: Run configured business evaluation\n        run: python -m pytest evaluation/test_evaluation.py -q\n      - uses: actions/upload-artifact@v4\n        if: always()\n        with:\n          name: eval-gate-report\n          path: evaluation/report.json\n"};
